    let ctl = new AbortController(), running = 0, seen, ready, asked = 0, done = 0, bytes = 0;
    const put = (pic, url) => { const i = new Image(); i.alt = ""; i.src = url; pic.replaceChildren(i); };
    const tell = () => {
