/* dark by default when the system says so; the header button overrides and is remembered */
:root, :root[data-theme=dark] {
  --bg: #16181c; --panel: #1f2227; --line: #33373e; --text: #e6e6e6; --dim: #9aa0a8; --shade: #16181cb0; --tipbg: #000d;
  --pink: rgb(255, 105, 200); --blue: rgb(0, 140, 255); --accent: #4c8dff; --yes: #2fb344; --no: #e5484d; --warn: #ffc864; --err: #ff7b7b;
  color-scheme: dark;
}
:root[data-theme=light] {
  --bg: #f4f5f7; --panel: #ffffff; --line: #d5d9e0; --text: #1c1f24; --dim: #5f6670; --shade: #f4f5f7c0; --tipbg: #fffffff0;
  --accent: #2f6fe0; --warn: #a86a00; --err: #c62828;
  color-scheme: light;
}
@media (prefers-color-scheme: light) {
  :root:not([data-theme]) {
    --bg: #f4f5f7; --panel: #ffffff; --line: #d5d9e0; --text: #1c1f24; --dim: #5f6670; --shade: #f4f5f7c0; --tipbg: #fffffff0;
    --accent: #2f6fe0; --warn: #a86a00; --err: #c62828;
    color-scheme: light;
  }
}
/* one spacing unit and three radii, used everywhere: panels, controls, chips */
/* a reason's letter keeps its colour from the lab's review sheets; on a light page it is darkened to stay readable */
:root { --ink-amt: 0%; }
:root[data-theme=light] { --ink-amt: 45%; }
@media (prefers-color-scheme: light) { :root:not([data-theme]) { --ink-amt: 45%; } }
.lt, .filter .badge { color: color-mix(in srgb, var(--c), #000 var(--ink-amt)); }
:root { --pad: 12px; --r-panel: 12px; --r-ctl: 8px; --r-chip: 6px; }
* { box-sizing: border-box; }
/* a fixed frame: header, three columns and the footer fill the window; only the columns scroll */
html, body { height: 100%; overflow: hidden; }
body { margin: 0; background: var(--bg); color: var(--text); font: 14px/1.4 system-ui, sans-serif;
  display: grid; grid-template-rows: 52px minmax(0, 1fr) 1cm; }
header { display: flex; gap: 14px; align-items: center; height: 52px; padding: 0 16px; border-bottom: 1px solid var(--line); }
#logo { height: 36px; width: auto; flex: none; }
h1 { font-size: 18px; margin: 0; flex: 1; }
h2 { font-size: 15px; margin: 0 0 6px; }
.dim { color: var(--dim); }
button, select, input { font: inherit; color: var(--text); background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-ctl); }
button { padding: 5px 12px; cursor: pointer; }
button:not(:disabled):hover { border-color: var(--dim); }
select, input[type=text], input[type=number] { padding: 4px 8px; background: var(--bg); }
input:focus-visible, select:focus-visible, button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
button:disabled { opacity: .45; cursor: default; }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
/* Load: a button with a dropdown beside it for where to load from */
.split { display: inline-flex; }
.split > button { border-radius: var(--r-ctl) 0 0 var(--r-ctl); font-weight: 600; padding: 4px 14px; }
.split .menu summary { border-radius: 0 var(--r-ctl) var(--r-ctl) 0; padding: 4px 8px; border-left: 1px solid #ffffff55; height: 100%; }
.split .menu summary.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.split .menu summary.primary::after { color: #fff; content: "▾"; }
#load.done .primary { background: var(--panel); border-color: var(--accent); color: var(--accent); }
#load.done .menu summary.primary { border-left-color: var(--accent); }
#load.done .menu summary.primary::after { color: var(--accent); }
.menu .pop.right { left: auto; right: 0; }
.menu .pop .item { text-align: left; border: 0; background: none; padding: 4px 2px; white-space: nowrap; }
.menu .pop .item:not(:disabled):hover { color: var(--accent); }

/* three columns of panels; the gutters between them are the handles that resize the side bars */
#layout { --lw: 320px; --rw: 400px; display: grid; grid-template-columns: var(--lw) var(--pad) minmax(0, 1fr) var(--pad) var(--rw);
  grid-template-rows: minmax(0, 1fr); min-height: 0; }
/* the scrollbar's room is kept even when nothing scrolls, so folding a box never changes the bar's width */
aside { overflow-y: auto; scrollbar-gutter: stable; scrollbar-width: thin; padding: var(--pad); }
#left { padding-right: 0; }
#right { padding-left: 0; }
.gutter { cursor: col-resize; position: relative; }
.gutter::after { content: ""; position: absolute; top: 50%; left: 50%; width: 3px; height: 36px; margin: -18px 0 0 -1.5px; border-radius: 2px; background: var(--line); opacity: 0; transition: opacity .15s; }
.gutter:hover::after, body.resizing .gutter::after { opacity: 1; }
body.resizing { cursor: col-resize; user-select: none; }
.box { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r-panel); padding: 14px; }
.box + .box { margin-top: var(--pad); }
.box h2 { margin-bottom: 10px; }
.box select { width: 100%; }
#thumb-wrap { position: relative; margin-bottom: 8px; border-radius: var(--r-ctl); overflow: hidden; background: #000; cursor: crosshair; line-height: 0; }
#thumb-wrap[hidden] { display: none; }
#thumb { width: 100%; height: auto; }
#thumb-view { position: absolute; border: 1.5px solid #fff; border-radius: 2px; box-shadow: 0 0 0 1px #0008; pointer-events: none; }
#file-box { margin: 0 0 10px; }
#file-name { display: flex; align-items: center; gap: 7px; word-break: break-all; font-size: 13px; cursor: pointer; list-style: none; }
#file-name::-webkit-details-marker { display: none; }
#file-name::before { content: ""; flex: none; width: 0; height: 0; border-style: solid; border-width: 5px 0 5px 7px;
  border-color: transparent transparent transparent var(--dim); transition: transform .15s; }
#file-box[open] > #file-name::before { transform: rotate(90deg); }
#file-box.empty > #file-name { cursor: default; pointer-events: none; }
#file-box.empty > #file-name::before { display: none; }
#file-info { display: grid; grid-template-columns: auto 1fr; gap: 2px 10px; margin: 6px 0 0 13px; font-size: 12px; }
#file-info dt { color: var(--dim); }
#file-info dd { margin: 0; overflow-wrap: anywhere; }
#file-info dd.none { grid-column: 1 / -1; margin-top: 2px; }
.layers { display: flex; gap: 14px; font-size: 13px; white-space: nowrap; }
.layers label { display: inline-flex; align-items: center; gap: 5px; cursor: pointer; }
/* a channel's checkbox takes the channel's colour when it is on */
input.ch { width: 15px; height: 15px; margin: 0; cursor: pointer; }
input.ch.r { accent-color: #f33; } input.ch.g { accent-color: #2fb344; } input.ch.b { accent-color: #3d6bff; }
.row { display: flex; justify-content: space-between; gap: 8px; margin-top: 12px; }
/* a button shines while it is the next thing to press */
.shine { position: relative; overflow: hidden; box-shadow: 0 0 10px var(--accent); }
.shine::after { pointer-events: none; content: ""; position: absolute; inset: 0; width: 40%;
  background: linear-gradient(100deg, transparent, #ffffff90, transparent); animation: shine 1.8s ease-in-out infinite; }
.offscreen, .offscreen::before, .offscreen::after { animation-play-state: paused !important; }
@keyframes shine { from { transform: translateX(-120%); } to { transform: translateX(320%); } }
/* folding parts of a box */
details.fold { margin-top: 10px; border-top: 1px solid var(--line); padding-top: 8px; }
details.fold > summary { display: flex; align-items: center; gap: 7px; cursor: pointer; font-size: 13px; font-weight: 600; color: var(--dim); list-style: none; }
details.fold > summary::-webkit-details-marker { display: none; }
/* every fold's arrow: a small triangle pointing right when folded and down when open, centred on its text */
details.fold > summary::before, .box.foldable > .sec-head h2::before { content: ""; flex: none; width: 0; height: 0;
  border-style: solid; border-width: 5px 0 5px 7px; border-color: transparent transparent transparent var(--dim); transition: transform .15s; }
details.fold[open] > summary::before, .box.foldable:not(.folded) > .sec-head h2::before { transform: rotate(90deg); }
.sec-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.sec-head h2, .sec-head button { margin: 0; white-space: nowrap; }
.box > .sec-head { margin-bottom: 10px; }
.box.foldable.folded > .sec-head { margin-bottom: 0; }
.sec-head button { padding: 3px 10px; font-size: 12px; }
button.link { border: 0; background: none; padding: 0; color: var(--accent); font-size: 12px; }
button.link:not(:disabled):hover { text-decoration: underline; }
button.link:disabled { color: var(--dim); }
.hint { color: var(--dim); font-size: 12px; margin: 4px 0 8px; }
.hint.slow { color: var(--warn); margin-bottom: 0; }

.help { display: inline-flex; align-items: center; justify-content: center; width: 14px; height: 14px; margin-left: 2px; border-radius: 50%;
  border: 1px solid var(--dim); color: var(--dim); font-size: 10px; font-weight: 700; line-height: 1; cursor: help; vertical-align: 1px; }
.help:hover, .help:focus-visible { color: var(--accent); border-color: var(--accent); outline: none; }
