  await page.click('#storage-list .group[data-group=thumbs] .entry[data-name="slide 1.tif"] .del');
  await page.waitForFunction(() => !document.querySelector('#storage-list .group[data-group=thumbs] .entry[data-name="slide 1.tif"]'));
